// Pull raw CSV text from HTTP Request node
const csv = $input.first().json.data || $input.first().json.body || $input.first().json;
const text = typeof csv === 'string' ? csv : JSON.stringify(csv);

// Parse CSV
const lines = text.trim().split(/\r?\n/);
const headers = lines[0].split(',').map(h => h.trim());
const idx = name => headers.indexOf(name);

const rows = lines.slice(1).map(line => {
  // simple CSV split — fine if no quoted commas in your data
  const cells = line.split(',');
  const obj = {};
  headers.forEach((h, i) => obj[h] = (cells[i] || '').trim());
  return obj;
});

const total_orders = rows.length;

// cancellation_rate from order_status column
const cancelled = rows.filter(r => (r.order_status || '').toLowerCase() === 'cancelled').length;
const cancellation_rate = total_orders ? cancelled / total_orders : 0;

// avg delivery time
const deliveryTimes = rows
  .map(r => parseFloat(r.delivery_time_mins))
  .filter(v => !isNaN(v));
const avg_delivery_time = deliveryTimes.length
  ? deliveryTimes.reduce((a, b) => a + b, 0) / deliveryTimes.length
  : 0;

// worst zone by complaint count
const complaintsByZone = {};
for (const r of rows) {
  const z = r.delivery_zone || 'Unknown';
  const c = parseInt(r.customer_complaints, 10);
  if (!isNaN(c)) complaintsByZone[z] = (complaintsByZone[z] || 0) + c;
}
const worst_zone = Object.entries(complaintsByZone)
  .sort((a, b) => b[1] - a[1])[0] || ['n/a', 0];

// worst restaurant by cancellation count
const cancelsByRestaurant = {};
for (const r of rows) {
  if ((r.order_status || '').toLowerCase() === 'cancelled') {
    const name = r.restaurant_name || 'Unknown';
    cancelsByRestaurant[name] = (cancelsByRestaurant[name] || 0) + 1;
  }
}
const worst_restaurant = Object.entries(cancelsByRestaurant)
  .sort((a, b) => b[1] - a[1])[0] || ['n/a', 0];

// top cancel-risk restaurant-zone pair (highest cancel_probability)
let top_pair = { restaurant: 'n/a', zone: 'n/a', prob: 0, alert: '' };
for (const r of rows) {
  const p = parseFloat(r.cancel_probability);
  if (!isNaN(p) && p > top_pair.prob) {
    top_pair = {
      restaurant: r.restaurant_name,
      zone: r.delivery_zone,
      prob: p,
      alert: (r.alert || '').slice(0, 300),
    };
  }
}

// yesterday's date (ISO)
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const date = yesterday.toISOString().slice(0, 10);

return [{
  json: {
    date,
    total_orders,
    cancelled_orders: cancelled,
    cancellation_rate: Number(cancellation_rate.toFixed(3)),
    cancellation_rate_pct: Math.round(cancellation_rate * 100),
    avg_delivery_time: Number(avg_delivery_time.toFixed(1)),
    worst_zone: worst_zone[0],
    worst_zone_complaints: worst_zone[1],
    worst_restaurant: worst_restaurant[0],
    worst_restaurant_cancels: worst_restaurant[1],
    top_pair_restaurant: top_pair.restaurant,
    top_pair_zone: top_pair.zone,
    top_pair_probability: Number(top_pair.prob.toFixed(3)),
    top_pair_alert: top_pair.alert,
  }
}];

